import { useEffect, useState } from "react";

/**
 * True once the page has scrolled past `threshold`.
 *
 * Position, not direction: the brief describes three states that all follow
 * from scroll offset — top bar plus transparent header at rest, solid sticky
 * header once moving, and the original state restored on return to the top.
 *
 * Reads are coalesced into a single animation frame so a fast wheel or an
 * inertial trackpad fling cannot queue up a burst of re-renders.
 */
export function useHeaderScroll(threshold: number): boolean {
  const [solid, setSolid] = useState(false);

  useEffect(() => {
    let frame = 0;

    const read = () => {
      frame = 0;
      setSolid(window.scrollY > threshold);
    };

    const onScroll = () => {
      if (frame) return;
      frame = requestAnimationFrame(read);
    };

    // Covers a reload part-way down the page, where no scroll event fires.
    read();

    window.addEventListener("scroll", onScroll, { passive: true });

    return () => {
      window.removeEventListener("scroll", onScroll);
      if (frame) cancelAnimationFrame(frame);
    };
  }, [threshold]);

  return solid;
}

export default useHeaderScroll;
