import React from "react";

import FooterX from "../ppm/primitives/footer/footer-x";
import HeaderX from "../ppm/primitives/header/header-x";

type Props = {
  children: React.ReactNode;
  /**
   * True when the page opens with full-bleed hero photography that should run
   * underneath the transparent header. False adds a spacer so ordinary page
   * content clears the fixed bar instead of starting behind it.
   */
  heroLed?: boolean;
};

/**
 * The site shell.
 *
 * One header and one footer for every page — interior pages reuse these, never
 * a copy.
 */
export default function Layout({ children, heroLed = false }: Props) {
  return (
    /* A column that fills the viewport, so a short page keeps the footer at the
       bottom of the screen rather than partway up it. See .kr-shell. */
    <div className="kr-shell">
      {/* A hero-led page runs its photography under a transparent header;
          every other page starts against a pale background and wants the
          header solid from the first paint. */}
      <HeaderX variant={heroLed ? "overlay" : "light"} />
      {heroLed ? null : <div className="kr-header-spacer" />}
      <main>{children}</main>
      <FooterX />
    </div>
  );
}
