import React, { useEffect, useState } from "react";
import { LuArrowUp } from "react-icons/lu";

type Props = {
  /** Distance scrolled, in px, before the control appears. */
  after: number;
  label: string;
};

/**
 * Back-to-top control.
 *
 * Hidden until the visitor has scrolled far enough that returning to the top
 * is actually a chore. Scroll reads are coalesced into one animation frame,
 * and the smooth scroll is skipped under prefers-reduced-motion — a full-page
 * glide is exactly the kind of movement that setting is asking to avoid.
 */
export default function BackToTop({ after, label }: Props) {
  const [shown, setShown] = useState(false);

  useEffect(() => {
    let frame = 0;

    const read = () => {
      frame = 0;
      setShown(window.scrollY > after);
    };
    const onScroll = () => {
      if (frame) return;
      frame = requestAnimationFrame(read);
    };

    read();
    window.addEventListener("scroll", onScroll, { passive: true });

    return () => {
      window.removeEventListener("scroll", onScroll);
      if (frame) cancelAnimationFrame(frame);
    };
  }, [after]);

  const toTop = () => {
    const reduced =
      typeof window.matchMedia === "function" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    window.scrollTo({ top: 0, behavior: reduced ? "auto" : "smooth" });
  };

  return (
    <button
      type="button"
      className={`kr-totop${shown ? " kr-totop--shown" : ""}`}
      aria-label={label}
      aria-hidden={!shown}
      tabIndex={shown ? 0 : -1}
      onClick={toTop}
    >
      <LuArrowUp size={17} strokeWidth={1.75} />
    </button>
  );
}
