// Styling for the site header and top bar. Swap via config/header--template.ts
// to restyle without touching a component.
//
// Two modifiers, deliberately separate:
//
//   --solid     colour: background, text, border, shadow, scrim
//   --scrolled  geometry: top bar collapse, bar height, wordmark size
//
// On the homepage both toggle together past the scroll threshold. On an
// interior page the header is solid from the start but its top bar still
// collapses on scroll, which only works because the two are not the same class.
//
// Everything else is described once, in CSS, rather than orchestrated frame by
// frame in JavaScript.
//
// The call to action carries no colour here: it wears `kr-btn kr-btn--gold`
// from the shared button system, so it stays gold in both states and changes
// with the buttons template rather than this file.

import template1 from "./template-1";

export type HeaderLabels = {
  /** aria-label for the primary navigation landmark. */
  navLabel: string;
  openMenu: string;
  closeMenu: string;
  /** aria-label for the home link on the wordmark. */
  homeLabel: string;
};

export type HeaderTemplate = {
  css: string;
  rootClass: string;
  timing: typeof template1.timing;
  layout: typeof template1.layout;
  labels: HeaderLabels;
};

const { color, layout, spacing, timing, typography } = template1;

const labels: HeaderLabels = {
  navLabel: "Primary",
  openMenu: "Open menu",
  closeMenu: "Close menu",
  homeLabel: "Kelley Road Property Management — home",
};

const ease = "cubic-bezier(.4, 0, .2, 1)";

const css = `
.kr-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: ${layout.zIndex};
  background-color: ${color.transparentBackground};
  border-bottom: 1px solid transparent;
  transition:
    background-color ${timing.stateChange}ms ${ease},
    border-color ${timing.stateChange}ms ${ease},
    box-shadow ${timing.stateChange}ms ${ease};
}
.kr-header--solid {
  background-color: ${color.solidBackground};
  border-bottom-color: ${color.solidBorder};
  box-shadow: ${color.solidShadow};
}

/* Scrim keeps white navigation legible over a bright photograph. */
.kr-header__scrim {
  position: absolute;
  inset: 0;
  background: ${color.scrim};
  opacity: 1;
  pointer-events: none;
  transition: opacity ${timing.stateChange}ms ${ease};
}
.kr-header--solid .kr-header__scrim { opacity: 0; }

.kr-header__inner {
  position: relative;
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
  height: 100%;
  display: flex;
  align-items: center;
  gap: ${spacing.ctaGap}px;
}

/* ── top bar ──────────────────────────────────────────── */
.kr-topbar {
  position: relative;
  height: ${layout.topBarHeight}px;
  background: ${color.topBarBackground};
  color: ${color.topBarText};
  overflow: hidden;
  opacity: 1;
  transition:
    height ${timing.topBarCollapse}ms ${ease},
    opacity ${timing.topBarCollapse}ms ${ease};
}
/* Collapse rather than display:none, so the bar slides away. */
.kr-header--scrolled .kr-topbar {
  height: 0;
  opacity: 0;
}

.kr-topbar__inner {
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
  height: ${layout.topBarHeight}px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: ${spacing.topBarGap}px;
}

.kr-topbar__group {
  display: flex;
  align-items: center;
  gap: ${spacing.topBarDividerGap}px;
  min-width: 0;
}

.kr-topbar__item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: ${color.topBarTextMuted};
  font-family: ${typography.topBarFamily};
  font-size: ${typography.topBarSize}px;
  font-weight: ${typography.topBarWeight};
  letter-spacing: ${typography.topBarTracking};
  text-transform: uppercase;
  text-decoration: none;
  white-space: nowrap;
  transition: color .2s ${ease};
}
a.kr-topbar__item:hover { color: ${color.topBarText}; }
a.kr-topbar__item:focus-visible {
  outline: 2px solid ${color.topBarIcon};
  outline-offset: 3px;
  border-radius: 2px;
}

/* The only gold in the bar, beyond the dividers. */
.kr-topbar__icon {
  display: inline-flex;
  color: ${color.topBarIcon};
  flex-shrink: 0;
}

.kr-topbar__divider {
  width: 1px;
  height: 11px;
  background: ${color.topBarDivider};
  flex-shrink: 0;
}

/* ── main bar ─────────────────────────────────────────── */
.kr-header__bar {
  position: relative;
  height: ${layout.barHeight}px;
  transition: height ${timing.stateChange}ms ${ease};
}
.kr-header--scrolled .kr-header__bar { height: ${layout.barHeightScrolled}px; }

/* ── wordmark ─────────────────────────────────────────── */
.kr-header__logo {
  display: inline-flex;
  align-items: baseline;
  margin-right: auto;
  color: ${color.transparentLogo};
  font-family: ${typography.logoFamily};
  font-size: ${typography.logoSize}px;
  font-weight: ${typography.logoWeight};
  letter-spacing: ${typography.logoTracking};
  line-height: 1;
  text-decoration: none;
  white-space: nowrap;
  transition:
    color ${timing.stateChange}ms ${ease},
    font-size ${timing.stateChange}ms ${ease};
}
.kr-header--solid .kr-header__logo { color: ${color.solidLogo}; }
.kr-header--scrolled .kr-header__logo { font-size: ${typography.logoSizeScrolled}px; }
.kr-header__logo-accent { color: ${color.transparentAccent}; }
.kr-header--solid .kr-header__logo-accent { color: ${color.solidAccent}; }
.kr-header__logo:focus-visible {
  outline: 2px solid ${color.transparentAccent};
  outline-offset: 6px;
  border-radius: 3px;
}

/* ── navigation ───────────────────────────────────────── */
.kr-header__nav {
  display: flex;
  align-items: center;
  gap: ${spacing.navGap}px;
}

.kr-header__link {
  position: relative;
  color: ${color.transparentLinkMuted};
  font-family: ${typography.navFamily};
  font-size: ${typography.navSize}px;
  font-weight: ${typography.navWeight};
  letter-spacing: ${typography.navTracking};
  text-decoration: none;
  padding: ${layout.navPaddingY}px 0;
  line-height: 1;
  white-space: nowrap;
  transition: color ${timing.stateChange}ms ${ease};
}
.kr-header--solid .kr-header__link { color: ${color.solidLinkMuted}; }

.kr-header__link::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -${layout.navUnderlineOffset}px;
  height: ${layout.navUnderlineHeight}px;
  background: ${color.transparentAccent};
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform .28s ${ease}, background-color ${timing.stateChange}ms ${ease};
}
.kr-header--solid .kr-header__link::after { background: ${color.solidAccent}; }

.kr-header__link:hover,
.kr-header__link--active { color: ${color.transparentLink}; }
.kr-header--solid .kr-header__link:hover,
.kr-header--solid .kr-header__link--active { color: ${color.solidLink}; }

.kr-header__link:hover::after,
.kr-header__link--active::after { transform: scaleX(1); }

.kr-header__link:focus-visible {
  outline: 2px solid ${color.transparentAccent};
  outline-offset: 4px;
  border-radius: 2px;
}

/* ── call to action ───────────────────────────────────────
   Layout only. Colour comes from kr-btn--gold. */
.kr-header__cta { flex-shrink: 0; }

/* ── hamburger ────────────────────────────────────────── */
.kr-header__burger {
  display: none;
  width: 36px;
  height: 36px;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
  position: relative;
  flex-shrink: 0;
}
.kr-header__burger span {
  position: absolute;
  left: 50%;
  width: ${layout.burgerSize}px;
  height: ${layout.burgerBarHeight}px;
  margin-left: -${layout.burgerSize / 2}px;
  border-radius: 2px;
  background: ${color.transparentLink};
  transition: background-color ${timing.stateChange}ms ${ease};
}
.kr-header--solid .kr-header__burger span { background: ${color.solidLink}; }
.kr-header__burger span:nth-child(1) { top: 11px; }
.kr-header__burger span:nth-child(2) { top: 17px; }
.kr-header__burger span:nth-child(3) { top: 23px; }
.kr-header__burger:focus-visible {
  outline: 2px solid ${color.transparentAccent};
  outline-offset: 2px;
  border-radius: 6px;
}

/* ── mobile drawer ────────────────────────────────────── */
.kr-drawer {
  position: fixed;
  inset: 0;
  z-index: ${layout.drawerZIndex};
  background: ${color.drawerBackground};
  display: flex;
  flex-direction: column;
  padding: 0 ${spacing.drawerPaddingX}px ${spacing.drawerPaddingX}px;
  transform: translateX(100%);
  visibility: hidden;
  transition:
    transform ${timing.drawer}ms ${ease},
    visibility 0s linear ${timing.drawer}ms;
}
.kr-drawer--open {
  transform: translateX(0);
  visibility: visible;
  transition:
    transform ${timing.drawer}ms ${ease},
    visibility 0s linear 0s;
}

.kr-drawer__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: ${layout.barHeightCompact}px;
  flex-shrink: 0;
}
.kr-drawer__logo {
  color: ${color.drawerText};
  font-family: ${typography.logoFamily};
  font-size: ${typography.logoSizeCompact}px;
  letter-spacing: ${typography.logoTracking};
  text-decoration: none;
}
.kr-drawer__logo-accent { color: ${color.drawerAccent}; }

.kr-drawer__close {
  width: 40px;
  height: 40px;
  border: 0;
  background: none;
  cursor: pointer;
  position: relative;
  flex-shrink: 0;
}
.kr-drawer__close span {
  position: absolute;
  top: 50%;
  left: 50%;
  width: ${layout.burgerSize}px;
  height: ${layout.burgerBarHeight}px;
  margin-left: -${layout.burgerSize / 2}px;
  border-radius: 2px;
  background: ${color.drawerText};
}
.kr-drawer__close span:nth-child(1) { transform: rotate(45deg); }
.kr-drawer__close span:nth-child(2) { transform: rotate(-45deg); }
.kr-drawer__close:focus-visible {
  outline: 2px solid ${color.drawerAccent};
  outline-offset: 2px;
  border-radius: 6px;
}

.kr-drawer__nav {
  display: flex;
  flex-direction: column;
  margin-top: 20px;
}
.kr-drawer__link {
  display: block;
  padding: ${spacing.drawerItemPaddingY}px 0;
  border-bottom: 1px solid ${color.drawerDivider};
  color: ${color.drawerText};
  font-family: ${typography.drawerFamily};
  font-size: ${typography.drawerSize}px;
  font-weight: ${typography.drawerWeight};
  letter-spacing: ${typography.logoTracking};
  text-decoration: none;
  transition: color .2s ${ease};
}
.kr-drawer__link:hover,
.kr-drawer__link--active { color: ${color.drawerAccent}; }

/* Layout only; colour comes from kr-btn--gold. */
.kr-drawer__cta {
  margin-top: 30px;
  align-self: flex-start;
}

.kr-drawer__meta {
  margin-top: auto;
  padding-top: 28px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.kr-drawer__meta-item {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: rgba(255, 255, 255, .72);
  font-family: ${typography.topBarFamily};
  font-size: 11px;
  letter-spacing: ${typography.topBarTracking};
  text-transform: uppercase;
  text-decoration: none;
}
.kr-drawer__meta-item .kr-topbar__icon { color: ${color.drawerAccent}; }

/* Spacer for pages that are not hero-led, so content clears the fixed bar. */
.kr-header-spacer { height: ${layout.topBarHeight + layout.barHeight}px; }

/* ── responsive ───────────────────────────────────────── */
@media (max-width: 1140px) {
  .kr-header__nav { gap: ${spacing.navGapTight}px; }
  /* Shed the softest top-bar detail before shedding the bar itself. */
  .kr-topbar__item--optional,
  .kr-topbar__item--optional + .kr-topbar__divider,
  .kr-topbar__divider + .kr-topbar__item--optional { display: none; }
}

@media (max-width: ${layout.navCollapseBelow}px) {
  .kr-header__nav,
  .kr-header__cta { display: none; }
  .kr-header__burger { display: block; }
  .kr-header__bar,
  .kr-header--scrolled .kr-header__bar { height: ${layout.barHeightCompact}px; }
  .kr-header__inner,
  .kr-topbar__inner { padding: 0 ${spacing.gutterCompact}px; }
  .kr-header__logo,
  .kr-header--scrolled .kr-header__logo { font-size: ${typography.logoSizeCompact}px; }
  .kr-header-spacer { height: ${layout.topBarHeight + layout.barHeightCompact}px; }
}

@media (max-width: ${layout.topBarHideBelow}px) {
  .kr-topbar { display: none; }
  .kr-header-spacer { height: ${layout.barHeightCompact}px; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-header,
  .kr-header__bar,
  .kr-header__scrim,
  .kr-topbar,
  .kr-header__logo,
  .kr-header__link,
  .kr-header__link::after,
  .kr-drawer {
    transition-duration: .01ms;
  }
}
`;

const template: HeaderTemplate = {
  css,
  rootClass: "kr-header",
  timing,
  layout,
  labels,
};

export default template;
